MERGE SYS_ATTRIBUTE_DEF_TRANS AS T
USING (
  SELECT sa.ATTRIBUTE_ID, sr.LanguageId AS LANGUAGE_ID, sr.TranslatedAttribute
  FROM @SourceRows sr
  INNER JOIN SYS_ATTRIBUTE_DEF sa ON sa.ATTRIBUTE = sr.AttributeName
  INNER JOIN SYS_LANGUAGE sl ON sl.LANGUAGE_ID = sr.LanguageId
) AS S
ON T.ATTRIBUTE_ID = S.ATTRIBUTE_ID AND T.LANGUAGE_ID = S.LANGUAGE_ID
WHEN MATCHED AND ISNULL(T.ATTRIBUTE, N'') <> S.TranslatedAttribute THEN
  UPDATE SET ATTRIBUTE = S.TranslatedAttribute
WHEN NOT MATCHED BY TARGET THEN
  INSERT (ATTRIBUTE_ID, LANGUAGE_ID, ATTRIBUTE)
  VALUES (S.ATTRIBUTE_ID, S.LANGUAGE_ID, S.TranslatedAttribute);

COMMIT TRAN;
PRINT N'Armenian (LANGUAGE_ID=10048) attribute translations seeded successfully.';
END TRY
BEGIN CATCH
  IF @@TRANCOUNT > 0 ROLLBACK TRAN;
  DECLARE @err NVARCHAR(4000) = ERROR_MESSAGE();
  RAISERROR(@err, 16, 1);
END CATCH;
